 "content": "def transform(grid):
    """Return a 3x3 tile of the color of the largest non-background component."""
    h, w = len(grid), len(grid[0])
    seen = set()
    largest_color = None
    largest_size = 0
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            size = 0
            while stack:
                y, x = stack.pop()
                size += 1
                for ny, nx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            if size > largest_size:
                largest_size = size
                largest_color = color
    if largest_color is None:
        return []
    return [[largest_color] * 3 for _ in range(3)]
